import{_ as t,o as e,c as o,aO as i}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"printf 转换说明与修饰符速查","description":"","frontmatter":{"date":"2026-10-08T20:30:00.000Z","title":"printf 转换说明与修饰符速查","source":[[["1-知识/C++/printf转换说明与修饰符"]],[["1-知识/C++/使用宏打印调试信息"]]],"tags":["编程语言","教程手册","C","printf"],"categories":["计算机"],"permalink":"/pages/24f520"},"headers":[],"relativePath":"计算机/printf 转换说明与修饰符速查.md","filePath":"计算机/printf 转换说明与修饰符速查.md","lastUpdated":1793152436000}'),s={name:"计算机/printf 转换说明与修饰符速查.md"};function a(c,d,n,r,l,h){return e(),o("div",null,[...d[0]||(d[0]=[i(`<h1 id="printf-转换说明与修饰符速查" tabindex="-1">printf 转换说明与修饰符速查 <a class="header-anchor" href="#printf-转换说明与修饰符速查" aria-label="Permalink to &quot;printf 转换说明与修饰符速查&quot;">​</a></h1> <p>printf() 的格式串由转换说明控制，转换说明用错是 C 语言初学阶段最常见的输出异常来源：打印出乱码、数值位数不对、字段对不齐。本文整理转换说明、修饰符、标记三类成分的完整含义与书写顺序，给出两个容易踩坑的细节（sizeof 的类型可移植性、float 参数的自动提升），并附一个带文件与行号定位的调试打印宏封装，顺带说清可变参数宏里 <code>##</code> 的特殊用法，可作为写格式串时的速查手册。</p> <h2 id="格式串的组成与书写顺序" tabindex="-1">格式串的组成与书写顺序 <a class="header-anchor" href="#格式串的组成与书写顺序" aria-label="Permalink to &quot;格式串的组成与书写顺序&quot;">​</a></h2> <p>一个完整的转换说明结构如下：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%[标记][最小字段宽度][.精度][长度修饰符]转换字符</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>除 <code>%</code> 和转换字符外，其余成分都可以省略。插入多个修饰符时，书写顺序应与上述结构一致，例如 <code>%-+10.2f</code>（左对齐、显式符号、宽度 10、精度 2、double），并非所有组合都有意义。</p> <h2 id="转换说明" tabindex="-1">转换说明 <a class="header-anchor" href="#转换说明" aria-label="Permalink to &quot;转换说明&quot;">​</a></h2> <p>转换说明（conversion specification）指定如何把数据转换成可显示的形式，打印指令要与待打印数据的类型匹配：</p> <table tabindex="0"><thead><tr><th>转换说明</th> <th>输出</th></tr></thead> <tbody><tr><td><code>%a</code></td> <td>浮点数、十六进制数和 p 记数法（C99/C11）</td></tr> <tr><td><code>%A</code></td> <td>浮点数、十六进制数和 P 记数法（C99/C11）</td></tr> <tr><td><code>%c</code></td> <td>单个字符</td></tr> <tr><td><code>%d</code></td> <td>有符号十进制整数</td></tr> <tr><td><code>%e</code></td> <td>浮点数，e 记数法</td></tr> <tr><td><code>%E</code></td> <td>浮点数，E 记数法</td></tr> <tr><td><code>%f</code></td> <td>浮点数，十进制记数法</td></tr> <tr><td><code>%F</code></td> <td>浮点数，十进制记数法（C99）</td></tr> <tr><td><code>%g</code></td> <td>根据值的不同，自动选择 <code>%f</code> 或 <code>%e</code>。<code>%e</code> 格式用于指数小于 -4 或大于等于精度时</td></tr> <tr><td><code>%G</code></td> <td>根据值的不同，自动选择 <code>%f</code> 或 <code>%E</code>。<code>%E</code> 格式用于指数小于 -4 或大于等于精度时</td></tr> <tr><td><code>%i</code></td> <td>有符号十进制整数（与 <code>%d</code> 相同）</td></tr> <tr><td><code>%o</code></td> <td>无符号八进制整数</td></tr> <tr><td><code>%p</code></td> <td>指针</td></tr> <tr><td><code>%s</code></td> <td>字符串</td></tr> <tr><td><code>%u</code></td> <td>无符号十进制整数</td></tr> <tr><td><code>%x</code></td> <td>无符号十六进制整数，用十六进制数字 af</td></tr> <tr><td><code>%X</code></td> <td>无符号十六进制整数，用十六进制数字 AF</td></tr> <tr><td><code>%%</code></td> <td>打印一个百分号</td></tr></tbody></table> <p>其中 <code>%a</code>/<code>%A</code>、<code>%F</code> 以及后文多个长度修饰符都是 C99 引入的，使用老编译器时需注意可用性。</p> <h2 id="修饰符" tabindex="-1">修饰符 <a class="header-anchor" href="#修饰符" aria-label="Permalink to &quot;修饰符&quot;">​</a></h2> <p>在 <code>%</code> 和转换字符之间插入修饰符，可以控制字段宽度与类型大小：</p> <table tabindex="0"><thead><tr><th>修饰符</th> <th>含义</th></tr></thead> <tbody><tr><td>标记</td> <td>5 种标记（<code>-</code>、<code>+</code>、空格、<code>#</code>、<code>0</code>），可以不使用或使用多个标记，示例：<code>&quot;%-10d&quot;</code></td></tr> <tr><td>数字</td> <td>最小字段宽度。如果该字段不能容纳待打印的数或字符串，系统会使用更宽的字段，示例：<code>&quot;%4d&quot;</code></td></tr> <tr><td><code>.数字</code></td> <td>精度。对于 <code>%e</code>、<code>%E</code>、<code>%f</code> 转换，表示小数点右边数字的位数；对于 <code>%g</code>、<code>%G</code> 转换，表示有效数字最大位数；对于 <code>%s</code> 转换，表示待打印字符的最大数量；对于整型转换，表示待打印数字的最小位数（如有必要，前面补零）。只使用 <code>.</code> 表示其后跟随一个 0，例如 <code>%.f</code> 与 <code>%.0f</code> 相同，示例：<code>&quot;%5.2f&quot;</code></td></tr> <tr><td><code>h</code></td> <td>和整型转换说明一起使用，表示 short int 或 unsigned short int 类型，示例：<code>&quot;%hu&quot;</code></td></tr> <tr><td><code>hh</code></td> <td>和整型转换说明一起使用，表示 signed char 或 unsigned char 类型，示例：<code>&quot;%hhu&quot;</code></td></tr> <tr><td><code>j</code></td> <td>和整型转换说明一起使用，表示 intmax_t 或 uintmax_t 类型，示例：<code>&quot;%jd&quot;</code></td></tr> <tr><td><code>l</code></td> <td>和整型转换说明一起使用，表示 long int 或 unsigned long int 类型，示例：<code>&quot;%ld&quot;</code></td></tr> <tr><td><code>ll</code></td> <td>和整型转换说明一起使用，表示 long long int 或 unsigned long long int 类型（C99），示例：<code>&quot;%lld&quot;</code></td></tr> <tr><td><code>L</code></td> <td>和浮点转换说明一起使用，表示 long double 类型，示例：<code>&quot;%Lf&quot;</code></td></tr> <tr><td><code>t</code></td> <td>和整型转换说明一起使用，表示 ptrdiff_t 类型（与两个指针差值的类型对应，C99），示例：<code>&quot;%td&quot;</code></td></tr> <tr><td><code>z</code></td> <td>和整型转换说明一起使用，表示 size_t 类型（C99），示例：<code>&quot;%zd&quot;</code></td></tr></tbody></table> <h2 id="标记" tabindex="-1">标记 <a class="header-anchor" href="#标记" aria-label="Permalink to &quot;标记&quot;">​</a></h2> <p>标记控制对齐、符号与输出形式：</p> <table tabindex="0"><thead><tr><th>标记</th> <th>含义</th></tr></thead> <tbody><tr><td><code>-</code></td> <td>待打印项左对齐，即从字段的左侧开始打印该项，示例：<code>&quot;%-20s&quot;</code></td></tr> <tr><td><code>+</code></td> <td>有符号值若为正，则在值前面显示加号；若为负，则在值前面显示减号，示例：<code>&quot;%+6.2f&quot;</code></td></tr> <tr><td>空格</td> <td>有符号值若为正，则在值前面显示前导空格（不显示任何符号）；若为负，则在值前面显示减号。<code>+</code> 标记覆盖一个空格，示例：<code>&quot;%6.2f&quot;</code></td></tr> <tr><td><code>#</code></td> <td>把结果转换为另一种形式。如果是 <code>%o</code> 格式，则以 0 开始；如果是 <code>%x</code> 格式，则以 0x 开始；如果是 <code>%X</code> 格式，则以 0X 开始。对于所有的浮点格式，<code>#</code> 保证了即使后面没有任何数字，也打印一个小数点字符。对于 <code>%g</code> 和 <code>%G</code> 格式，<code>#</code> 防止结果后面的 0 被删除，示例：<code>&quot;%#o&quot;</code>、<code>&quot;%#8.0f&quot;</code></td></tr> <tr><td><code>0</code></td> <td>对于数值格式，用前导 0 代替空格填充字段宽度。对于整数格式，如果出现 <code>-</code> 标记或指定精度，则忽略该标记，示例：<code>&quot;%010d&quot;</code>、<code>&quot;%08.3f&quot;</code></td></tr></tbody></table> <h2 id="两个容易踩坑的细节" tabindex="-1">两个容易踩坑的细节 <a class="header-anchor" href="#两个容易踩坑的细节" aria-label="Permalink to &quot;两个容易踩坑的细节&quot;">​</a></h2> <p><strong>sizeof 的类型可移植性</strong>。sizeof 运算符以字节为单位返回类型或值的大小，标准只规定了该值是无符号整数。在不同的实现中，它可以是 unsigned int、unsigned long 甚至是 unsigned long long。如果要用 printf() 显示 sizeof 表达式，根据不同系统，可能使用 <code>%u</code>、<code>%lu</code> 或 <code>%llu</code>，把程序移植到其他系统时还要进行修改。C 提供了可移植性更好的类型别名：stddef.h 头文件（在包含 stdio.h 时已包含其中）把 size_t 定义为 sizeof 返回的类型，printf() 应使用 <code>%zd</code> 转换说明打印 size_t 类型；对于两个指针的差值，C 标准提供了 ptrdiff_t 类型（定义在 stddef.h 中）和对应的 <code>%td</code> 转换说明（C99）。</p> <p><strong>float 参数的自动提升</strong>。对于浮点常量和 float 类型变量，printf() 都使用 <code>%f</code>、<code>%e</code> 等浮点转换说明。由于 C 语言中 float 类型的值在作为参数传递时会被自动提升为 double 类型（默认参数提升），printf() 的 float 类型参数实际上会先转换为 double 再传入，因此没有 float 专用的转换说明，也不需要。</p> <h2 id="用宏封装调试打印" tabindex="-1">用宏封装调试打印 <a class="header-anchor" href="#用宏封装调试打印" aria-label="Permalink to &quot;用宏封装调试打印&quot;">​</a></h2> <p>格式速查解决「打印什么」，调试场景往往还需要「在哪里打印」：文件、行号、函数名每次手写繁琐且容易漏，用宏封装一次即可：</p> <div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DBG_PRINTF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">fmt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">args</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...)                              </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {                                                      </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;&lt;File:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Line:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Function:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&gt;&gt; &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,          </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">               __FILE__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__LINE__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">__FUNCTION__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);             </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fmt, ##args);                                  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><code>__FILE__</code>、<code>__LINE__</code> 在展开处分别替换为当前源文件名与行号，<code>__FUNCTION__</code> 替换为函数名（前两个是标准预定义宏，<code>__FUNCTION__</code> 是编译器扩展，标准写法见下文）。</li> <li><code>do { } while (0)</code> 把多条语句包成一条，保证宏在 <code>if</code>/<code>else</code> 分支里安全使用。</li></ul> <h3 id="、-与可变参数的坑" tabindex="-1"><code>#</code>、<code>##</code> 与可变参数的坑 <a class="header-anchor" href="#、-与可变参数的坑" aria-label="Permalink to &quot;\`#\`、\`##\` 与可变参数的坑&quot;">​</a></h3> <ul><li><code>#</code> 把宏参数字符串化：<code>#x</code> 展开为 <code>&quot;x&quot;</code>。</li> <li><code>##</code> 是记号连接符，常见用途是拼接变量名；但放在<strong>逗号与可变参数之间</strong>时有特殊含义——可变参数为空时，它前面的逗号会被一并删除。上例中 <code>fmt, ##args</code> 正是这个用法：<code>DBG_PRINTF(&quot;done\\n&quot;)</code> 不带额外参数也能编译通过；参数非空时按原样拼接。</li> <li>给可变参数命名（<code>args...</code>）是 GNU 扩展；C99 标准写法是 <code>...</code> 配 <code>__VA_ARGS__</code>，两种写法不能混用。标准写法里去逗号用 <code>##__VA_ARGS__</code>（同为编译器扩展），C++20 与 C23 起可用标准的 <code>__VA_OPT__(,)</code> 替代。</li> <li>严格可移植的场合，函数名用 C99 起预定义的标识符 <code>__func__</code> 替代 <code>__FUNCTION__</code>。</li></ul> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>转换说明必须与待打印类型匹配，书写顺序为：<code>% 标记 宽度 .精度 长度修饰符 转换字符</code></li> <li>打印 sizeof 的结果用 <code>%zd</code>，指针差值用 <code>%td</code>，避免跨平台换 <code>%u</code>/<code>%lu</code></li> <li>float 参数会自动提升为 double，直接用 <code>%f</code> 即可</li> <li><code>0</code> 标记在指定精度或与 <code>-</code> 标记同用时会被忽略</li> <li>可变参数宏里 <code>##</code> 放在逗号与可变参数之间，参数为空时删掉逗号（GNU 扩展，标准替代是 <code>__VA_OPT__</code>）</li></ul> <p>（格式串部分依据《C Primer Plus》第 4 章整理，转换说明与修饰符行为以 C99/C11 标准为准；宏封装部分依据 GCC CPP 手册 Variadic Macros 节。）</p>`,53)])])}const u=t(s,[["render",a]]);export{k as __pageData,u as default};
